INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (1, 'I Tempi Verbali', 'Di solito io ______ al lavoro in autobus.', '[{"text":"vado","is_correct":true},{"text":"va","is_correct":false},{"text":"andiamo","is_correct":false},{"text":"vanno","is_correct":false}]'::jsonb, 'Con il pronome personale ''io'' si usa la prima persona singolare del presente indicativo di andare: ''vado''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (1, 'I Tempi Verbali', 'Oggi ______ la macchina.', '[{"text":"prendiamo","is_correct":false},{"text":"prende","is_correct":false},{"text":"prendi","is_correct":false},{"text":"prendo","is_correct":true}]'::jsonb, 'La frase si riferisce alla prima persona (''io prendo la macchina'').', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (1, 'I Tempi Verbali', 'Marco ______ sempre la colazione alle 7.', '[{"text":"fa","is_correct":true},{"text":"fai","is_correct":false},{"text":"fanno","is_correct":false},{"text":"faccio","is_correct":false}]'::jsonb, 'Marco corrisponde alla terza persona singolare (''lui''), quindi si coniuga ''fa'' (verbo fare).', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (1, 'I Tempi Verbali', 'Noi ______ in una casa grande.', '[{"text":"vivete","is_correct":false},{"text":"vivono","is_correct":false},{"text":"vivi","is_correct":false},{"text":"viviamo","is_correct":true}]'::jsonb, 'Con il pronome ''noi'' la desinenza del presente indicativo è ''-iamo'': ''viviamo''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (1, 'I Tempi Verbali', 'Stamattina io ______ il pane al supermercato.', '[{"text":"ho comprare","is_correct":false},{"text":"sono comprato","is_correct":false},{"text":"comprato","is_correct":false},{"text":"ho comprato","is_correct":true}]'::jsonb, 'Il verbo ''comprare'' richiede l''ausiliare ''avere'' al passato prossimo: ''ho comprato''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (1, 'I Tempi Verbali', 'I ragazzi ______ dal treno alle otto.', '[{"text":"sono scesi","is_correct":true},{"text":"hanno sceso","is_correct":false},{"text":"sono sceso","is_correct":false},{"text":"hanno scesi","is_correct":false}]'::jsonb, 'Il verbo di movimento ''scendere'' richiede l''ausiliare ''essere'' e concorda in genere e numero col soggetto plurale (''ragazzi'' -> ''sono scesi'').', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (1, 'I Tempi Verbali', 'Oggi Anna esce con gli amici. Ieri ______ con loro.', '[{"text":"è uscita","is_correct":true},{"text":"ha uscito","is_correct":false},{"text":"era uscita","is_correct":false},{"text":"è uscito","is_correct":false}]'::jsonb, 'Uscire è intransitivo di movimento, richiede ''essere'' come ausiliare e concorda con il soggetto femminile singolare Anna (''è uscita'').', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (1, 'I Tempi Verbali', 'Ieri sera Maria ______ una pizza.', '[{"text":"è mangiata","is_correct":false},{"text":"ha mangiata","is_correct":false},{"text":"ha mangiato","is_correct":true},{"text":"è mangiato","is_correct":false}]'::jsonb, '''Mangiare'' richiede l''ausiliare ''avere''. Il participio passato resta invariato in ''-o'' in assenza di pronomi diretti antecedenti.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (1, 'I Tempi Verbali', 'I miei genitori ______ in Italia nel 1990.', '[{"text":"sono andati","is_correct":true},{"text":"sono andato","is_correct":false},{"text":"hanno andato","is_correct":false},{"text":"sono andate","is_correct":false}]'::jsonb, 'Andare richiede l''ausiliare ''essere''. Essendo ''i miei genitori'' maschile plurale, il participio è ''andati''.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (1, 'I Tempi Verbali', 'Lucia ______ un bel film al cinema ieri.', '[{"text":"ha vedere","is_correct":false},{"text":"è visto","is_correct":false},{"text":"è vista","is_correct":false},{"text":"ha visto","is_correct":true}]'::jsonb, 'Vedere richiede l''ausiliare ''avere'': ''ha visto'' (participio irregolare).', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (1, 'I Tempi Verbali', 'Ieri ______ un libro.', '[{"text":"ho comprato","is_correct":true},{"text":"compravo","is_correct":false},{"text":"ho comprare","is_correct":false},{"text":"comprai","is_correct":false}]'::jsonb, 'Per un''azione puntuale e conclusa nel passato si usa il passato prossimo: ''ho comprato''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (1, 'I Tempi Verbali', 'Da bambino ______ sempre al parco.', '[{"text":"giocavo","is_correct":true},{"text":"giocato","is_correct":false},{"text":"ho giocato","is_correct":false},{"text":"giocherò","is_correct":false}]'::jsonb, 'Per descrivere un''azione abituale o ripetuta nel passato si usa l''imperfetto: ''giocavo''.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (1, 'I Tempi Verbali', 'Mentre ______, ha telefonato Marco.', '[{"text":"mangiavo","is_correct":true},{"text":"ho mangiato","is_correct":false},{"text":"mangia","is_correct":false},{"text":"mangerò","is_correct":false}]'::jsonb, 'La congiunzione ''mentre'' introduce un''azione continuativa sullo sfondo nel passato, espressa con l''imperfetto (''mangiavo''). L''interruzione è al passato prossimo.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (1, 'I Tempi Verbali', 'Quando ero piccola, ______ un gatto nero.', '[{"text":"aveva","is_correct":false},{"text":"avevo","is_correct":true},{"text":"ho avuto","is_correct":false},{"text":"ebbi","is_correct":false}]'::jsonb, 'Gli stati fisici, mentali o il possesso continuativo nel passato richiedono l''imperfetto: ''avevo''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (1, 'I Tempi Verbali', 'Ieri sera ______ quando siamo usciti.', '[{"text":"piove","is_correct":false},{"text":"ha piovuto","is_correct":false},{"text":"pioveva","is_correct":true},{"text":"pioverà","is_correct":false}]'::jsonb, 'Le descrizioni del tempo meteorologico nel passato richiedono l''imperfetto: ''pioveva''.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (1, 'I Tempi Verbali', 'Stamattina mi ______ alle 6.', '[{"text":"sono svegliato","is_correct":true},{"text":"ho svegliato","is_correct":false},{"text":"sono svegliata","is_correct":true},{"text":"sveglio","is_correct":false}]'::jsonb, 'I verbi riflessivi richiedono sempre l''ausiliare ''essere'' al passato prossimo (se l''utente è maschio ''mi sono svegliato'', se femmina ''mi sono svegliata''). Entrambi corretti.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (1, 'I Tempi Verbali', 'La mattina io ______ alle 7.', '[{"text":"si sveglia","is_correct":false},{"text":"mi sveglio","is_correct":true},{"text":"sveglio mi","is_correct":false},{"text":"mi svegliano","is_correct":false}]'::jsonb, 'Il verbo riflessivo presente per la prima persona singolare è ''mi sveglio''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (1, 'I Tempi Verbali', 'Voi ______ sempre tardi.', '[{"text":"vi addormentate","is_correct":true},{"text":"vi addormenti","is_correct":false},{"text":"addormentatevi","is_correct":false},{"text":"si addormentano","is_correct":false}]'::jsonb, 'La forma riflessiva per ''voi'' è ''vi addormentate''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (1, 'I Tempi Verbali', 'Marco ______ in fretta la mattina.', '[{"text":"ti vesti","is_correct":false},{"text":"vestesi","is_correct":false},{"text":"si vestono","is_correct":false},{"text":"si veste","is_correct":true}]'::jsonb, 'La terza persona singolare riflessiva di vestirsi è ''si veste''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (1, 'I Tempi Verbali', 'Ieri sera Maria ______ molto al cinema.', '[{"text":"ha divertito","is_correct":false},{"text":"si ha divertito","is_correct":false},{"text":"si è divertita","is_correct":true},{"text":"è divertita","is_correct":false}]'::jsonb, 'Divertirsi al passato prossimo richiede ''essere'' ed accordo col soggetto femminile singolare: ''si è divertita''.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (1, 'I Tempi Verbali', 'Domani noi ______ al mare.', '[{"text":"andremmo","is_correct":false},{"text":"andremo","is_correct":true},{"text":"andranno","is_correct":false},{"text":"andiamo","is_correct":false}]'::jsonb, 'Azione futura pianificata: si coniuga al futuro semplice prima persona plurale (''andremo'').', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (1, 'I Tempi Verbali', '______ un caffè, per favore.', '[{"text":"Vorrebbe","is_correct":false},{"text":"Voglio","is_correct":false},{"text":"Vorrei","is_correct":true},{"text":"Vorrei essere","is_correct":false}]'::jsonb, '''Vorrei'' è il condizionale di cortesia di volere, usato per ordinare in modo gentile.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (1, 'I Tempi Verbali', 'Se io avessi tempo, ______ al cinema.', '[{"text":"andrò","is_correct":false},{"text":"andassi","is_correct":false},{"text":"andrei","is_correct":true},{"text":"andrei a","is_correct":false}]'::jsonb, 'Periodo ipotetico del secondo tipo (possibilità): Congiuntivo imperfetto nella secondaria (''avessi'') + Condizionale presente nella principale (''andrei'').', 3, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (1, 'I Tempi Verbali', 'Se tu ______ di più, prenderesti voti migliori.', '[{"text":"studieresti","is_correct":false},{"text":"studiassi","is_correct":true},{"text":"studiasti","is_correct":false},{"text":"studi","is_correct":false}]'::jsonb, 'Periodo ipotetico con condizionale nella principale (''prenderesti'') richiede il congiuntivo imperfetto nella subordinata introdotta da se: ''studiassi''.', 3, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (1, 'I Tempi Verbali', 'Se noi avessimo una macchina, ______ più luoghi.', '[{"text":"visiteranno","is_correct":false},{"text":"visitassimo","is_correct":false},{"text":"visiteremo","is_correct":false},{"text":"visiteremmo","is_correct":true}]'::jsonb, 'Periodo ipotetico di secondo tipo: se + congiuntivo imperfetto (''avessimo'') richiede il condizionale presente (''visiteremmo'').', 3, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (1, 'I Tempi Verbali', 'Noi ______ partiti ieri per Torino.', '[{"text":"siamo","is_correct":true},{"text":"eravamo","is_correct":false},{"text":"abbiamo","is_correct":false},{"text":"saremo","is_correct":false}]'::jsonb, 'Partire richiede l''ausiliare essere. Poiché l''azione è avvenuta ieri, si usa il passato prossimo: ''siamo partiti''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (1, 'I Tempi Verbali', 'Quando tu ______ telefonato, io dormivo.', '[{"text":"hai","is_correct":true},{"text":"sei","is_correct":false},{"text":"eri","is_correct":false},{"text":"avevi","is_correct":false}]'::jsonb, 'Telefonare è un verbo transitivo che richiede avere: ''hai telefonato'' (azione puntuale passata che interrompe un''azione continuativa ''dormivo'').', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (1, 'I Tempi Verbali', 'Fra un mese ______ l''esame CLA di italiano.', '[{"text":"farei","is_correct":false},{"text":"faccio","is_correct":false},{"text":"ho fatto","is_correct":false},{"text":"farò","is_correct":true}]'::jsonb, 'Azione futura pianificata espressa con il futuro semplice prima persona singolare: ''farò''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (1, 'I Tempi Verbali', 'Penso che quel film ______ molto bello.', '[{"text":"sia","is_correct":true},{"text":"è","is_correct":false},{"text":"sarebbe","is_correct":false},{"text":"fossi","is_correct":false}]'::jsonb, 'Il verbo ''pensare che'' esprime un''opinione e richiede il congiuntivo presente: ''sia''.', 3, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (1, 'I Tempi Verbali', 'Non sapevo che voi ______ già arrivati.', '[{"text":"eravate","is_correct":false},{"text":"sareste","is_correct":false},{"text":"foste","is_correct":true},{"text":"siete","is_correct":false}]'::jsonb, 'Frase subordinata al passato che richiede el congiuntivo trapassato (congiuntivo imperfetto di essere ''foste'' + participio ''arrivati'').', 3, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (2, 'La Casa', 'In cucina c''è un tavolo con quattro ______.', '[{"text":"letti","is_correct":false},{"text":"sedie","is_correct":true},{"text":"armadi","is_correct":false},{"text":"finestre","is_correct":false}]'::jsonb, 'Intorno a un tavolo in cucina si mettono solitamente le ''sedie''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (2, 'La Casa', 'In soggiorno abbiamo comprato un ______ a tre posti molto comodo.', '[{"text":"frigorifero","is_correct":false},{"text":"lavandino","is_correct":false},{"text":"balcone","is_correct":false},{"text":"divano","is_correct":true}]'::jsonb, 'Un mobile a tre posti per sedersi o sdraiarsi in soggiorno è il ''divano''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (2, 'La Casa', 'Ho messo il latte e lo yogurt nel ______ per tenerli freschi.', '[{"text":"letto","is_correct":false},{"text":"lavastoviglie","is_correct":false},{"text":"forno","is_correct":false},{"text":"frigorifero","is_correct":true}]'::jsonb, 'La conservazione di latte e yogurt richiede il ''frigorifero''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (2, 'La Casa', 'Dobbiamo lavare i vestiti sporchi, metti tutto nella ______.', '[{"text":"lavatrice","is_correct":true},{"text":"vasca","is_correct":false},{"text":"doccia","is_correct":false},{"text":"lavastoviglie","is_correct":false}]'::jsonb, 'L''elettrodomestico per lavare i vestiti è la ''lavatrice''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (2, 'La Casa', 'In camera da letto c''è un grande ______ per vestiti e giacche.', '[{"text":"tavolino","is_correct":false},{"text":"tappeto","is_correct":false},{"text":"armadio","is_correct":true},{"text":"frigorifero","is_correct":false}]'::jsonb, 'L''armadio si usa per conservare vestiti e giacche nella camera da letto.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (2, 'La Casa', 'Sul letto ci sono due ______ morbidi per appoggiare la testa.', '[{"text":"cuscini","is_correct":true},{"text":"quadri","is_correct":false},{"text":"tavoli","is_correct":false},{"text":"specchi","is_correct":false}]'::jsonb, 'Si appoggia la testa sui ''cuscini'' quando si dorme nel letto.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (2, 'La Casa', 'Il gatto sta dormendo ______ il letto, non sopra.', '[{"text":"sotto","is_correct":true},{"text":"in","is_correct":false},{"text":"su","is_correct":false},{"text":"di","is_correct":false}]'::jsonb, 'Il contrario di ''sopra'' è ''sotto''.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (2, 'La Casa', 'Accanto al letto ho messo un ______ con una pequeña lampada.', '[{"text":"comodino","is_correct":true},{"text":"divano","is_correct":false},{"text":"lavello","is_correct":false},{"text":"balcone","is_correct":false}]'::jsonb, 'Il mobiletto basso accanto al letto è il ''comodino''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (2, 'La Casa', 'Nel bagno c''è sia la doccia che la ______ da bagno.', '[{"text":"vasca","is_correct":true},{"text":"lavatrice","is_correct":false},{"text":"sedia","is_correct":false},{"text":"cucina","is_correct":false}]'::jsonb, 'In bagno si può avere la doccia o la ''vasca da bagno''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (2, 'La Casa', 'In salotto ______ due poltrone e un televisore.', '[{"text":"sono","is_correct":false},{"text":"c''è","is_correct":false},{"text":"ci sono","is_correct":true},{"text":"è","is_correct":false}]'::jsonb, 'Per indicare la presenza di elementi al plurale (''due poltrone'') si usa ''ci sono''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (2, 'La Casa', 'In questo appartamento non ______ un balcone.', '[{"text":"ci sono","is_correct":false},{"text":"ha","is_correct":false},{"text":"c''è","is_correct":true},{"text":"è","is_correct":false}]'::jsonb, 'Si usa ''c''è'' per indicare la presenza o l''esistenza di un elemento singolare (''un balcone'').', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (2, 'La Casa', 'La spazzatura si trova ______ il lavello della cucina.', '[{"text":"in","is_correct":false},{"text":"su","is_correct":false},{"text":"tra","is_correct":false},{"text":"sotto","is_correct":true}]'::jsonb, 'La pattumiera solitamente si posiziona ''sotto'' il lavandino (lavello) in cucina.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (2, 'La Casa', 'La chiave è ______ porta, puoi prenderla.', '[{"text":"nella","is_correct":true},{"text":"sulla","is_correct":false},{"text":"sotto la","is_correct":false},{"text":"dietro","is_correct":false}]'::jsonb, 'La chiave si trova inserita ''nella'' serratura della porta.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (2, 'La Casa', 'Il forno a microonde si trova ______ al frigorifero.', '[{"text":"sopra","is_correct":false},{"text":"tra","is_correct":false},{"text":"accanto","is_correct":true},{"text":"in","is_correct":false}]'::jsonb, 'Si dice ''accanto a'' per indicare la vicinanza laterale.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (2, 'La Casa', 'Per specchiarsi in bagno c''è un grande ______ appeso alla parete.', '[{"text":"specchio","is_correct":true},{"text":"tappeto","is_correct":false},{"text":"quadro","is_correct":false},{"text":"cassetto","is_correct":false}]'::jsonb, 'Ci si specchia nello ''specchio''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (2, 'La Casa', 'La notte dormo nella mia ______ da letto.', '[{"text":"cucina","is_correct":false},{"text":"camera","is_correct":true},{"text":"cantina","is_correct":false},{"text":"soggiorno","is_correct":false}]'::jsonb, 'Si dorme in camera da letto.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (2, 'La Casa', 'Laviamo i piatti sporchi a mano nel ______ della cucina.', '[{"text":"forno","is_correct":false},{"text":"vasca","is_correct":false},{"text":"armadio","is_correct":false},{"text":"lavello","is_correct":true}]'::jsonb, 'Il lavandino della cucina è comunemente chiamato ''lavello''.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (2, 'La Casa', 'Il riscaldamento è spento, la casa è molto ______.', '[{"text":"fredda","is_correct":true},{"text":"calda","is_correct":false},{"text":"nuova","is_correct":false},{"text":"luminosa","is_correct":false}]'::jsonb, 'Se il riscaldamento è spento, la casa diventa ''fredda''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (2, 'La Casa', 'Il mio appartamento è al terzo piano e c''è un comodo ______.', '[{"text":"ascensore","is_correct":true},{"text":"giardino","is_correct":false},{"text":"garage","is_correct":false},{"text":"tetto","is_correct":false}]'::jsonb, 'Per salire ai piani alti si usa l''ascensore.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (2, 'La Casa', 'La mia stanza ha una ______ che dà sul cortile interno.', '[{"text":"scrivania","is_correct":false},{"text":"parete","is_correct":false},{"text":"sedia","is_correct":false},{"text":"finestra","is_correct":true}]'::jsonb, 'Una finestra permette di vedere l''esterno.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (2, 'La Casa', 'In corridoio c''è un mobile basso con tre ______ per i documenti.', '[{"text":"cassetti","is_correct":true},{"text":"letti","is_correct":false},{"text":"divani","is_correct":false},{"text":"bagni","is_correct":false}]'::jsonb, 'Un mobile basso ha solitamente dei ''cassetti'' per riporre oggetti.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (2, 'La Casa', 'L''auto è parcheggiata nel ______ condominiale.', '[{"text":"garage","is_correct":true},{"text":"corridoio","is_correct":false},{"text":"soggiorno","is_correct":false},{"text":"cucina","is_correct":false}]'::jsonb, 'L''automobile si parcheggia nel garage.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (3, 'I Pronomi', 'Vedi Maria? Sì, ______ vedo ogni giorno.', '[{"text":"la","is_correct":true},{"text":"li","is_correct":false},{"text":"lo","is_correct":false},{"text":"le","is_correct":false}]'::jsonb, 'Pronominale diretto femminile singolare riferito a Maria: ''la''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (3, 'I Pronomi', 'Compri i giornali? Sì, ______ compro ogni mattina.', '[{"text":"li","is_correct":true},{"text":"le","is_correct":false},{"text":"la","is_correct":false},{"text":"l''","is_correct":false}]'::jsonb, 'Pronominale diretto maschile plurale riferito a i giornali: ''li''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (3, 'I Pronomi', 'Telefoni a Maria? Sì, ______ telefono stasera.', '[{"text":"ci","is_correct":false},{"text":"le","is_correct":true},{"text":"gli","is_correct":false},{"text":"la","is_correct":false}]'::jsonb, 'Pronominale indiretto femminile singolare riferito a Maria (''a lei''): ''le''.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (3, 'I Pronomi', 'Scrivi a Marco? Sì, ______ scrivo un''email.', '[{"text":"le","is_correct":false},{"text":"gli","is_correct":true},{"text":"lo","is_correct":false},{"text":"ci","is_correct":false}]'::jsonb, 'Pronominale indiretto maschile singolare riferito a Marco (''a lui''): ''gli''.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (3, 'I Pronomi', 'Hai visto le ragazze? Sì, ______ ho viste.', '[{"text":"le","is_correct":true},{"text":"li","is_correct":false},{"text":"la","is_correct":false},{"text":"le ho visto","is_correct":false}]'::jsonb, 'Pronome diretto ''le'' (femminile plurale) + passato prossimo richiede l''accordo del participio passato al plurale femminile (''viste'').', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (3, 'I Pronomi', 'Cosa dici a Paolo e Anna? ______ dico la verità.', '[{"text":"Loro","is_correct":false},{"text":"Gli","is_correct":true},{"text":"Li","is_correct":false},{"text":"Le","is_correct":false}]'::jsonb, 'Il pronome indiretto per la terza persona plurale (''a Paolo e Anna'' -> ''a loro'') prima del verbo è ''gli'' (o colloquiale/tradizionale ''dico loro''). In questo caso prima del verbo usiamo ''gli''.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (3, 'I Pronomi', 'Chi accompagna a scuola i bambini? ______ accompagna il papà.', '[{"text":"Li","is_correct":true},{"text":"Lo","is_correct":false},{"text":"Le","is_correct":false},{"text":"Gli","is_correct":false}]'::jsonb, 'Pronominale diretto riferito ai bambini (maschile plurale): ''li''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (3, 'I Pronomi', 'Hai comprato il latte? Sì, ______ ho comprato stamattina.', '[{"text":"l''","is_correct":true},{"text":"lo","is_correct":false},{"text":"la","is_correct":false},{"text":"li","is_correct":false}]'::jsonb, 'Il pronome ''lo'' si apostrofa davanti alla voce verbale ''ho'' diventando ''l'''': ''l''ho comprato''.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (3, 'I Pronomi', 'Hai invitato Giulia alla festa? Sì, ______ ho invitata.', '[{"text":"la ho","is_correct":false},{"text":"le","is_correct":false},{"text":"la","is_correct":false},{"text":"l''","is_correct":true}]'::jsonb, 'Il pronome ''la'' davanti a ''ho'' diventa ''l'''' e si fa l''accordo del participio ''invitata''.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (3, 'I Pronomi', 'Signora Rossi, ______ posso aiutare?', '[{"text":"La","is_correct":true},{"text":"la","is_correct":false},{"text":"ti","is_correct":false},{"text":"le","is_correct":false}]'::jsonb, 'Nella forma di cortesia (formale) si usa il pronome ''La'' con la lettera maiuscola, riferito a una persona singolare.', 3, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (3, 'I Pronomi', 'Ragazzi, ______ invito a cena sabato sera.', '[{"text":"ci","is_correct":false},{"text":"vi ho","is_correct":false},{"text":"vi","is_correct":true},{"text":"li","is_correct":false}]'::jsonb, 'Il pronome diretto per la seconda persona plurale (''voi'') è ''vi''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (3, 'I Pronomi', 'Hai telefonato ai tuoi amici? Sì, ______ ho telefonato ieri.', '[{"text":"ci","is_correct":false},{"text":"gli","is_correct":true},{"text":"li","is_correct":false},{"text":"le","is_correct":false}]'::jsonb, 'Il verbo telefonare regge a chi (''a loro'' -> pronominale indiretto ''gli'').', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (3, 'I Pronomi', 'Chi ti ha prestato questa penna? ______ ha prestata Lucia.', '[{"text":"Me la","is_correct":false},{"text":"Me lo","is_correct":false},{"text":"Me l''","is_correct":true},{"text":"Mi la","is_correct":false}]'::jsonb, 'Pronome combinato: ''mi'' (a me) + ''la'' (la penna) davanti ad ausiliare avere diventa ''me l''ha prestata''.', 3, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (3, 'I Pronomi', 'Hai dato il regalo a tuo fratello? Sì, ______ ho dato.', '[{"text":"gliel''","is_correct":true},{"text":"glielo","is_correct":false},{"text":"gli lo","is_correct":false},{"text":"lo gli","is_correct":false}]'::jsonb, 'Pronominale combinato ''gli'' (a lui) + ''lo'' (il regalo) davanti ad ausiliare avere con H si contrae in ''gliel''ho dato''.', 3, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (3, 'I Pronomi', 'Chi pulisce la casa? ______ pulisco io.', '[{"text":"La","is_correct":true},{"text":"Lo","is_correct":false},{"text":"Le","is_correct":false},{"text":"La ho","is_correct":false}]'::jsonb, 'Pronome diretto femminile singolare riferito a ''la casa'': ''la''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (3, 'I Pronomi', 'Ci dai le risposte del test? Sì, ______ do subito.', '[{"text":"ce le","is_correct":false},{"text":"ve le","is_correct":true},{"text":"ve li","is_correct":false},{"text":"vi le","is_correct":false}]'::jsonb, 'Pronominale combinato: ''vi'' (a voi, diventa ''ve'') + ''le'' (le risposte): ''ve le do''.', 3, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (3, 'I Pronomi', 'Hai offerto un caffè ai colleghi? Sì, ______ ho offerto uno.', '[{"text":"gli li","is_correct":false},{"text":"lo gli","is_correct":false},{"text":"gli lo","is_correct":false},{"text":"gliene","is_correct":true}]'::jsonb, 'Pronome combinato indiretto ''gli'' (a loro) + partitivo ''ne'' (di caffè): ''gliene ho offerto uno''.', 3, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (3, 'I Pronomi', 'Porti la torta alla festa? Sì, ______ porto più tardi.', '[{"text":"ci","is_correct":false},{"text":"lo","is_correct":false},{"text":"la","is_correct":true},{"text":"le","is_correct":false}]'::jsonb, 'Pronome diretto riferito a ''la torta'' (femminile singolare): ''la''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (3, 'I Pronomi', 'Hai spedito la lettera a Marco? Sì, ______ ho spedita.', '[{"text":"gli la","is_correct":false},{"text":"gliela","is_correct":false},{"text":"gliel''","is_correct":true},{"text":"la gli","is_correct":false}]'::jsonb, 'Pronome combinato ''gli'' (a lui) + ''la'' (la lettera) diventa ''gliela'' e davanti a ho si contrae in ''gliel''ho spedita'' (con accordo al femminile).', 3, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (3, 'I Pronomi', 'Ci porti al parco oggi? Sì, ______ porto volentieri.', '[{"text":"ci","is_correct":false},{"text":"li","is_correct":false},{"text":"ti","is_correct":false},{"text":"vi","is_correct":true}]'::jsonb, 'Rispondendo alla domanda con ''ci'' (noi), si usa ''vi'' (voi): ''vi porto volentieri''.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (3, 'I Pronomi', 'Hai mangiato tutti i cioccolatini? No, ______ ho mangiati solo due.', '[{"text":"lo","is_correct":false},{"text":"ne","is_correct":true},{"text":"ne ho","is_correct":false},{"text":"li","is_correct":false}]'::jsonb, 'Il pronome partitivo ''ne'' esprime una quantità definita di un insieme (''due cioccolatini''). Il participio concorda col numero (''mangiati'').', 3, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (3, 'I Pronomi', 'Hai bisogno di aiuto? Sì, ______ ho molto bisogno.', '[{"text":"gli","is_correct":false},{"text":"ci","is_correct":false},{"text":"lo","is_correct":false},{"text":"ne","is_correct":true}]'::jsonb, 'Aver bisogno ''di qualcosa'' richiede il pronome partitivo/argomento ''ne'': ''ne ho molto bisogno''.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (4, 'Le Preposizioni', 'Che lavoro fa tuo padre? È ______ falegname.', '[{"text":"un","is_correct":true},{"text":"il","is_correct":false},{"text":"uno","is_correct":false},{"text":"lo","is_correct":false}]'::jsonb, 'Davanti a nomi maschili singolari che iniziano per consonante normale si usa l''articolo indeterminativo ''un''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (4, 'Le Preposizioni', 'Perché sei adirato? Perché ______ insegnante mi ha rimproverato.', '[{"text":"l''","is_correct":true},{"text":"lo","is_correct":false},{"text":"il","is_correct":false},{"text":"la","is_correct":false}]'::jsonb, 'Insegnante inizia per vocale, quindi l''articolo determinativo si apostrofa diventando ''l''''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (4, 'Le Preposizioni', 'Sei figlio unico? No, ho ______ sorella.', '[{"text":"una","is_correct":true},{"text":"un''","is_correct":false},{"text":"la","is_correct":false},{"text":"un","is_correct":false}]'::jsonb, 'Articolo indeterminativo per nomi femminili singolari che iniziano per consonante: ''una''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (4, 'Le Preposizioni', 'Quale animale vorresti avere? Vorrei tanto ______ scoiattolo.', '[{"text":"uno","is_correct":true},{"text":"un","is_correct":false},{"text":"lo","is_correct":false},{"text":"l''","is_correct":false}]'::jsonb, 'Davanti a parole maschili che iniziano con ''s + consonante'' si usa l''articolo indeterminativo ''uno''.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (4, 'Le Preposizioni', 'Perché piangi? Perché mi fanno male ______ denti.', '[{"text":"i","is_correct":true},{"text":"gli","is_correct":false},{"text":"le","is_correct":false},{"text":"i miei","is_correct":false}]'::jsonb, 'Articolo determinativo plurale maschile davanti a consonante normale: ''i''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (4, 'Le Preposizioni', 'Perché stai risparmiando? Per pagare ______ rate della macchina.', '[{"text":"delle","is_correct":false},{"text":"i","is_correct":false},{"text":"gli","is_correct":false},{"text":"le","is_correct":true}]'::jsonb, 'Articolo determinativo plurale femminile: ''le''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (4, 'Le Preposizioni', 'Com''è la tua classe? ______ alunni sono molto diligenti.', '[{"text":"Le","is_correct":false},{"text":"Gli","is_correct":true},{"text":"I","is_correct":false},{"text":"Gli e","is_correct":false}]'::jsonb, 'Articolo determinativo plurale maschile davanti a nomi che iniziano per vocale: ''gli''.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (4, 'Le Preposizioni', 'Devi studiare? Sì, ma non più di ______ ora.', '[{"text":"un''","is_correct":true},{"text":"una","is_correct":false},{"text":"l''","is_correct":false},{"text":"un","is_correct":false}]'::jsonb, 'Articolo indeterminativo femminile singolare davanti a parola che inizia per vocale si apostrofa: ''un''''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (4, 'Le Preposizioni', 'Vado ______ scuola ogni mattina.', '[{"text":"in","is_correct":false},{"text":"da","is_correct":false},{"text":"su","is_correct":false},{"text":"a","is_correct":true}]'::jsonb, 'Si usa la preposizione semplice ''a'' con l''espressione ''andare a scuola''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (4, 'Le Preposizioni', 'Il libro è ______ tavolo.', '[{"text":"sopra","is_correct":false},{"text":"nel","is_correct":false},{"text":"in","is_correct":false},{"text":"sul","is_correct":true}]'::jsonb, 'Preposizione articolata ''su + il'' = ''sul'' (sopra la superficie del tavolo).', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (4, 'Le Preposizioni', 'Vengo ______ Italia.', '[{"text":"da","is_correct":false},{"text":"in","is_correct":false},{"text":"della","is_correct":false},{"text":"dall''","is_correct":true}]'::jsonb, 'Provenienza geografica da una nazione: ''venire da'' + articolo determinativo (l''Italia) = ''dall''Italia''.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (4, 'Le Preposizioni', 'Parliamo ______ vacanze.', '[{"text":"da le","is_correct":false},{"text":"delle","is_correct":true},{"text":"per le","is_correct":false},{"text":"alle","is_correct":false}]'::jsonb, 'Argomento: ''parlare di'' + articolo plurale femminile (le vacanze) = ''delles vacanze''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (4, 'Le Preposizioni', 'Abito ______ Roma ______ cinque anni.', '[{"text":"a / di","is_correct":false},{"text":"a / per","is_correct":false},{"text":"in / da","is_correct":false},{"text":"a / da","is_correct":true}]'::jsonb, 'Con i nomi di città si usa ''a''. Per indicare una durata nel presente (azione iniziata nel passato e ancora in corso) si usa la preposizione ''da''.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (4, 'Le Preposizioni', 'Vado ______ dentista domani.', '[{"text":"dal","is_correct":true},{"text":"al","is_correct":false},{"text":"da","is_correct":false},{"text":"in","is_correct":false}]'::jsonb, 'Moto a luogo verso una persona/professionista: ''da'' + articolo determinativo (il dentista) = ''dal dentista''.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (4, 'Le Preposizioni', '______ fratello si chiama Marco.', '[{"text":"Un mio","is_correct":false},{"text":"Il mio","is_correct":false},{"text":"Mio","is_correct":true},{"text":"Lo mio","is_correct":false}]'::jsonb, 'Non si usa l''articolo determinativo con i nomi di famiglia al singolare preceduti da aggettivo possessivo (tranne ''loro'').', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (4, 'Le Preposizioni', '______ sorelle vivono a Milano.', '[{"text":"Delle mie","is_correct":false},{"text":"I miei","is_correct":false},{"text":"Mie","is_correct":false},{"text":"Le mie","is_correct":true}]'::jsonb, 'I nomi di parentela al plurale richiedono l''articolo prima del possessivo: ''le mie sorelle''.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (4, 'Le Preposizioni', 'Dove sono ______ chiavi?', '[{"text":"le mia","is_correct":false},{"text":"mie","is_correct":false},{"text":"le mie","is_correct":true},{"text":"i miei","is_correct":false}]'::jsonb, 'Chiave è femminile plurale (''chiavi''), quindi richiede l''articolo e possessivo femminile plurale: ''le mie''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (4, 'Le Preposizioni', '______ casa è molto grande.', '[{"text":"Nostra","is_correct":false},{"text":"Il nostro","is_correct":false},{"text":"Della nostra","is_correct":false},{"text":"La nostra","is_correct":true}]'::jsonb, 'Gli aggettivi possessivi con nomi comuni richiedono l''articolo: ''la nostra casa''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (4, 'Le Preposizioni', 'Lui ama ______ mamma.', '[{"text":"il suo","is_correct":false},{"text":"sua","is_correct":false},{"text":"la sua","is_correct":true},{"text":"la mia","is_correct":false}]'::jsonb, 'I nomi di parentela modificati da vezzeggiativi (''mamma'', ''papà'') mantengono l''articolo con il possessivo: ''la sua mamma''.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (4, 'Le Preposizioni', 'I quaderni sono ______ zaino.', '[{"text":"in lo","is_correct":false},{"text":"sullo","is_correct":false},{"text":"nel","is_correct":false},{"text":"nello","is_correct":true}]'::jsonb, 'Stato in luogo dentro qualcosa che inizia con ''z'': ''in + lo'' = ''nello''.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (4, 'Le Preposizioni', 'Stasera vado ______ cinema con gli amici.', '[{"text":"in","is_correct":false},{"text":"a","is_correct":false},{"text":"al","is_correct":true},{"text":"nel","is_correct":false}]'::jsonb, 'Moto a luogo: andare + articolo + cinema = ''al cinema'' (a + il).', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (4, 'Le Preposizioni', 'Questo regalo è ______ te.', '[{"text":"per","is_correct":true},{"text":"a","is_correct":false},{"text":"da","is_correct":false},{"text":"di","is_correct":false}]'::jsonb, 'Destinazione d''uso o destinatario: preposizione semplice ''per''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (5, 'Tempo Libero', 'A Marco piace moltissimo ______ la TV la sera.', '[{"text":"guardando","is_correct":false},{"text":"guarda","is_correct":false},{"text":"guardato","is_correct":false},{"text":"guardare","is_correct":true}]'::jsonb, 'Dopo ''piace'' si usa il verbo all''infinito per indicare l''azione gradita.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (5, 'Tempo Libero', 'Nel fine settimana mi piace ______ a tennis con mio fratello.', '[{"text":"correre","is_correct":false},{"text":"fare","is_correct":false},{"text":"giocando","is_correct":false},{"text":"giocare","is_correct":true}]'::jsonb, 'Con sport con la palla (tennis) si usa el verbo ''giocare a''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (5, 'Tempo Libero', 'Non mi ______ i film dell''orrore.', '[{"text":"piacciono i","is_correct":false},{"text":"piace","is_correct":false},{"text":"piacciono di","is_correct":false},{"text":"piacciono","is_correct":true}]'::jsonb, 'Il soggetto logico è plurale (''i film''), quindi si usa la terza persona plurale ''piacciono''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (5, 'Tempo Libero', 'Ieri pomeriggio noi ______ una lunga passeggiata in centro.', '[{"text":"abbiamo fare","is_correct":false},{"text":"facciamo","is_correct":false},{"text":"abbiamo fatto","is_correct":true},{"text":"siamo fatti","is_correct":false}]'::jsonb, 'Espressione ''fare una passeggiata'' coniugata al passato prossimo con ausiliare avere: ''abbiamo fatto''.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (5, 'Tempo Libero', 'Due volte alla settimana vado in piscina e ______ nuoto.', '[{"text":"faccio","is_correct":true},{"text":"gioco","is_correct":false},{"text":"pratico","is_correct":false},{"text":"fai","is_correct":false}]'::jsonb, 'Per il nuoto si usa il verbo ''fare'': ''fare nuoto''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (5, 'Tempo Libero', 'Nel tempo libero adoro ______ libri di fantascienza.', '[{"text":"leggere","is_correct":true},{"text":"scrivere","is_correct":false},{"text":"ascoltare","is_correct":false},{"text":"comprare","is_correct":false}]'::jsonb, 'Leggere i libri è l''azione adatta all''oggetto.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (5, 'Tempo Libero', 'Il sabato sera usciamo spesso ______ gli amici.', '[{"text":"per","is_correct":false},{"text":"tra","is_correct":false},{"text":"con","is_correct":true},{"text":"a","is_correct":false}]'::jsonb, 'Compagnia: preposizione ''con''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (5, 'Tempo Libero', 'Ti va di andare ______ cinema stasera?', '[{"text":"a","is_correct":false},{"text":"al","is_correct":true},{"text":"nel","is_correct":false},{"text":"in","is_correct":false}]'::jsonb, 'Moto a luogo con ''cinema'' prende ''al'' (''a + il'').', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (5, 'Tempo Libero', 'D''estate mi piace andare ______ spiaggia a prendere il sole.', '[{"text":"a","is_correct":false},{"text":"sulla","is_correct":false},{"text":"in","is_correct":true},{"text":"alla","is_correct":false}]'::jsonb, 'Andare ''in spiaggia'' è un''espressione idiomatica molto comune.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (5, 'Tempo Libero', 'Ti ______ lo sport? Sì, molto.', '[{"text":"piace","is_correct":true},{"text":"piacciono","is_correct":false},{"text":"piaci","is_correct":false},{"text":"piaceva","is_correct":false}]'::jsonb, '''Lo sport'' è singolare, quindi si usa ''piace''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (5, 'Tempo Libero', 'Mio padre fa ______ ogni mattina per tenersi in forma.', '[{"text":"partita","is_correct":false},{"text":"calcio","is_correct":false},{"text":"il tennis","is_correct":false},{"text":"jogging","is_correct":true}]'::jsonb, 'Si dice ''fare jogging'' (correre per allenarsi).', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (5, 'Tempo Libero', 'Preferisco ______ musica classica rispetto a quella pop.', '[{"text":"ascoltare","is_correct":false},{"text":"sentire","is_correct":false},{"text":"udire","is_correct":false},{"text":"ascoltare la","is_correct":true}]'::jsonb, 'Ascoltare la musica classica è l''espressione corretta.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (5, 'Tempo Libero', 'Durante il weekend mi piace ______ a lungo.', '[{"text":"partire","is_correct":false},{"text":"studiare","is_correct":false},{"text":"lavorare","is_correct":false},{"text":"dormire","is_correct":true}]'::jsonb, 'Nel weekend, tipicamente si riposa e si ''dorme''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (5, 'Tempo Libero', 'Loro amano viaggiare ______ treno.', '[{"text":"in","is_correct":true},{"text":"con","is_correct":false},{"text":"nel","is_correct":false},{"text":"a","is_correct":false}]'::jsonb, 'I mezzi di trasporto prendono la preposizione ''in'': ''in treno''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (5, 'Tempo Libero', 'Vorrei prenotare un ______ per il concerto di stasera.', '[{"text":"biglietto","is_correct":true},{"text":"tavolo","is_correct":false},{"text":"camera","is_correct":false},{"text":"treno","is_correct":false}]'::jsonb, 'Per un concerto si acquista o prenota un ''biglietto''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (5, 'Tempo Libero', 'Ci piace fare ______ in montagna d''inverno.', '[{"text":"sci","is_correct":true},{"text":"nuoto","is_correct":false},{"text":"calcio","is_correct":false},{"text":"ginnastica","is_correct":false}]'::jsonb, 'In montagna sulla neve in inverno si fa ''sci''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (5, 'Tempo Libero', 'Qual è il tuo ______ preferito? La lettura.', '[{"text":"colore","is_correct":false},{"text":"hobby","is_correct":true},{"text":"lavoro","is_correct":false},{"text":"esame","is_correct":false}]'::jsonb, 'La lettura è un passatempo, quindi un ''hobby''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (5, 'Tempo Libero', 'Domenica prossima noi ______ a vedere una mostra d''arte.', '[{"text":"andremo","is_correct":true},{"text":"andiamo","is_correct":false},{"text":"siamo andati","is_correct":false},{"text":"andremmo","is_correct":false}]'::jsonb, 'Si riferisce a domenica prossima, azione futura espressa con il futuro semplice: ''andremo''.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (5, 'Tempo Libero', 'Se ho tempo libero, ______ volentieri a fare la spesa.', '[{"text":"andrei","is_correct":false},{"text":"sono andato","is_correct":false},{"text":"vado","is_correct":true},{"text":"andassi","is_correct":false}]'::jsonb, 'Periodo ipotetico della realtà al presente: se + presente (''ho'') richiede il presente indicativo (''vado'').', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (5, 'Tempo Libero', 'A loro non piace per niente ______ in televisione.', '[{"text":"guardare le partite","is_correct":true},{"text":"guardare","is_correct":false},{"text":"vedere","is_correct":false},{"text":"le partite","is_correct":false}]'::jsonb, '''Guardare le partite'' (all''infinito) completa correttamente la frase.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (5, 'Tempo Libero', 'Ogni sabato noi ______ la pizza in pizzeria.', '[{"text":"mangiano","is_correct":false},{"text":"mangiate","is_correct":false},{"text":"mangiamo","is_correct":true},{"text":"mangeremo","is_correct":false}]'::jsonb, 'Ogni sabato esprime abitudine, coniugato al presente prima persona plurale (''mangiamo'').', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (5, 'Tempo Libero', 'I bambini giocano a ______ nel giardino.', '[{"text":"nascondino","is_correct":true},{"text":"nuoto","is_correct":false},{"text":"giocattoli","is_correct":false},{"text":"correre","is_correct":false}]'::jsonb, 'Nascondino (el escondite) è un gioco infantile che si fa all''aperto: ''giocare a nascondino''.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (6, 'Le Persone', 'Roma è ______ grande ______ Firenze.', '[{"text":"più / che","is_correct":false},{"text":"così / di","is_correct":false},{"text":"più / di","is_correct":true},{"text":"meno / che","is_correct":false}]'::jsonb, 'Comparazione tra due nomi propri basata sulla grandezza: ''più grande di''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (6, 'Le Persone', 'Questo ristorante è ______ dell''altro.', '[{"text":"migliore","is_correct":true},{"text":"più buono","is_correct":false},{"text":"meglio","is_correct":false},{"text":"peggiore","is_correct":false}]'::jsonb, 'Il comparativo di maggioranza irregolare dell''aggettivo ''buono'' è ''migliore''.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (6, 'Le Persone', 'Il fratello di mio padre è mio ______.', '[{"text":"nonno","is_correct":false},{"text":"zio","is_correct":true},{"text":"nipote","is_correct":false},{"text":"cugino","is_correct":false}]'::jsonb, 'Definizione di parentela: lo zio è il fratello del padre o della madre.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (6, 'Le Persone', 'Mia sorella è ______ alta di me.', '[{"text":"di più","is_correct":false},{"text":"meglio","is_correct":false},{"text":"molto","is_correct":false},{"text":"più","is_correct":true}]'::jsonb, 'Struttura del comparativo: più + aggettivo + di.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (6, 'Le Persone', 'Giovanni è molto pigro, non fa mai niente. Al contrario, suo fratello è ______.', '[{"text":"lavoratore","is_correct":true},{"text":"intelligente","is_correct":false},{"text":"triste","is_correct":false},{"text":"timido","is_correct":false}]'::jsonb, 'Il contrario di pigro (perezoso) nel contesto dell''operosità è ''lavoratore'' (trabajador) o attivo.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (6, 'Le Persone', 'Com''è Maria di carattere? È molto ______ e allegra.', '[{"text":"magra","is_correct":false},{"text":"bassa","is_correct":false},{"text":"simpatica","is_correct":true},{"text":"rossa","is_correct":false}]'::jsonb, 'Le opzioni descrivono l''aspetto fisico tranne ''simpatica'', che si adatta alla domanda sul carattere.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (6, 'Le Persone', 'Oggi mi sento molto ______ perché ho superato l''esame CLA con 30!', '[{"text":"stanco","is_correct":false},{"text":"felice","is_correct":true},{"text":"arrabbiato","is_correct":false},{"text":"triste","is_correct":false}]'::jsonb, 'Superare un esame con il massimo dei voti rende felici.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (6, 'Le Persone', 'Lui è più basso ______ suo fratello maggiore.', '[{"text":"da","is_correct":false},{"text":"del","is_correct":false},{"text":"che","is_correct":false},{"text":"di","is_correct":true}]'::jsonb, 'Comparazione di minoranza/maggioranza davanti a possessivo senza articolo (''suo fratello''): si usa la preposizione semplice ''di''.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (6, 'Le Persone', 'Maria ha i capelli ______ e gli occhi verdi.', '[{"text":"magri","is_correct":false},{"text":"biondi","is_correct":true},{"text":"alti","is_correct":false},{"text":"simpatici","is_correct":false}]'::jsonb, 'I capelli possono essere ''biondi'' (castani, neri, rossi). Le altre parole non descrivono i capelli.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (6, 'Le Persone', 'Questa pizza è ______ di quella che abbiamo mangiato ieri.', '[{"text":"peggiore","is_correct":true},{"text":"peggio","is_correct":false},{"text":"migliore","is_correct":true},{"text":"più cattiva","is_correct":false}]'::jsonb, 'Sia ''peggiore'' (irregular de cattivo) che ''migliore'' (irregular de buono) sono grammaticalmente corretti. Impostiamo migliore come corretta.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (6, 'Le Persone', 'Io studio meno ore ______ te.', '[{"text":"che","is_correct":false},{"text":"di","is_correct":true},{"text":"da","is_correct":false},{"text":"del","is_correct":false}]'::jsonb, 'Comparazione tra due pronomi/nomi: meno + sostantivo + di + pronome.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (6, 'Le Persone', 'Mio nonno ha 80 anni, è la persona più ______ della famiglia.', '[{"text":"magra","is_correct":false},{"text":"alta","is_correct":false},{"text":"giovane","is_correct":false},{"text":"anziana","is_correct":true}]'::jsonb, 'Una persona di 80 anni è tipicamente la più ''anziana'' (o vecchia).', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (6, 'Le Persone', 'Le persone egoiste pensano solo a ______ stesse.', '[{"text":"si","is_correct":false},{"text":"se","is_correct":true},{"text":"loro","is_correct":false},{"text":"noi","is_correct":false}]'::jsonb, 'Pensare a se stessi: pronome riflessivo di terza persona dopo preposizione è ''se''.', 3, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (6, 'Le Persone', 'Quando Marco perde le chiavi di casa, si ______ molto.', '[{"text":"addormenta","is_correct":false},{"text":"diverte","is_correct":false},{"text":"sveglia","is_correct":false},{"text":"arrabbia","is_correct":true}]'::jsonb, 'Perdere le chiavi provoca rabbia, quindi ''si arrabbia'' (verbo riflessivo arrabbiarsi).', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (6, 'Le Persone', 'La figlia di mia sorella è mia ______.', '[{"text":"nipote","is_correct":true},{"text":"cugina","is_correct":false},{"text":"zia","is_correct":false},{"text":"nonna","is_correct":false}]'::jsonb, 'La figlia della sorella o del fratello è la ''nipote'' (sobrina).', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (6, 'Le Persone', 'Luca fa molto sport ed è molto ______.', '[{"text":"pigro","is_correct":false},{"text":"atletico","is_correct":true},{"text":"antipatico","is_correct":false},{"text":"grasso","is_correct":false}]'::jsonb, 'Chi fa molto sport è atletico o in forma.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (6, 'Le Persone', 'Ieri ero molto ______ perché non ho dormito bene.', '[{"text":"stanco","is_correct":true},{"text":"felice","is_correct":false},{"text":"simpatico","is_correct":false},{"text":"allegro","is_correct":false}]'::jsonb, 'Non dormire bene causa stanchezza (''stanco'').', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (6, 'Le Persone', 'Giulia è una persona molto ______: parla con tutti facilmente.', '[{"text":"timida","is_correct":false},{"text":"triste","is_correct":false},{"text":"antipatica","is_correct":false},{"text":"socievole","is_correct":true}]'::jsonb, 'Chi parla facilmente con tutti è ''socievole'' (sociable).', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (6, 'Le Persone', 'Mio cugino è ______ giovane di mio fratello.', '[{"text":"meglio","is_correct":false},{"text":"più","is_correct":true},{"text":"di più","is_correct":false},{"text":"molto","is_correct":false}]'::jsonb, 'Costruzione del comparativo di maggioranza: più + aggettivo + di.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (6, 'Le Persone', 'Il figlio di mio zio è mio ______.', '[{"text":"cugino","is_correct":true},{"text":"fratello","is_correct":false},{"text":"nipote","is_correct":false},{"text":"nonno","is_correct":false}]'::jsonb, 'Il figlio dello zio è il ''cugino'' (primo).', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (6, 'Le Persone', 'Mia madre ha gli occhi ______.', '[{"text":"azzurri","is_correct":true},{"text":"alti","is_correct":false},{"text":"azzurro","is_correct":false},{"text":"biondi","is_correct":false}]'::jsonb, 'L''aggettivo ''azzurri'' concorda in genere e numero con il sostantivo maschile plurale ''occhi''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (6, 'Le Persone', 'Questo esercizio è ______ difficile del precedente.', '[{"text":"peggio","is_correct":false},{"text":"più","is_correct":true},{"text":"meglio","is_correct":false},{"text":"molto","is_correct":false}]'::jsonb, 'Uso corretto del comparativo di maggioranza con aggettivo: ''più difficile del''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (7, 'Alimentazione', 'Il tiramisù è un tipico ______.', '[{"text":"primo piatto","is_correct":false},{"text":"pesce","is_correct":false},{"text":"dessert","is_correct":true},{"text":"contorno","is_correct":false}]'::jsonb, 'Il tiramisù è un dolce al cucchiaio, quindi un dessert.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (7, 'Alimentazione', 'Vorrei ______ acqua gassata, per favore.', '[{"text":"della","is_correct":false},{"text":"dell''","is_correct":true},{"text":"un''","is_correct":false},{"text":"dello","is_correct":false}]'::jsonb, 'Articolo partitivo femminile singolare davanti a parola que inizia per vocale: ''di + l'''' = ''dell''''.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (7, 'Alimentazione', 'Al mercato ho comprato ______ arance biologiche.', '[{"text":"dello","is_correct":false},{"text":"dei","is_correct":false},{"text":"delle","is_correct":true},{"text":"delle gli","is_correct":false}]'::jsonb, 'Articolo partitivo femminile plurale: ''di + le'' = ''delle'' (alcune arance).', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (7, 'Alimentazione', 'Cameriere, ci porta ______ sale? Manca sul tavolo.', '[{"text":"dello","is_correct":false},{"text":"al","is_correct":false},{"text":"la","is_correct":false},{"text":"del","is_correct":true}]'::jsonb, 'Articolo partitivo maschile singolare davanti a consonante semplice s: ''di + il'' = ''del''.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (7, 'Alimentazione', 'Non bevo mai ______ caffè il pomeriggio.', '[{"text":"del","is_correct":false},{"text":"dello","is_correct":false},{"text":"il","is_correct":false},{"text":"caffè","is_correct":true}]'::jsonb, 'Nelle frasi negative, spesso l''articolo partitivo viene omesso o si usa l''articolo determinativo/nulla: ''Non bevo mai caffè''. Qui l''opzione corretta è ''caffè'' senza preposizione o l''articolo determinativo. Mettiamo ''caffè''.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (7, 'Alimentazione', 'Per preparare la pasta al pomodoro servono ______ pomodori freschi.', '[{"text":"dei","is_correct":true},{"text":"delle","is_correct":false},{"text":"degli","is_correct":false},{"text":"del","is_correct":false}]'::jsonb, 'Articolo partitivo maschile plurale: ''di + i'' = ''dei''.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (7, 'Alimentazione', 'Cosa prendi come secondo? Prendo ______ ai ferri.', '[{"text":"il pollo","is_correct":true},{"text":"la pasta","is_correct":false},{"text":"il tiramisù","is_correct":false},{"text":"la zuppa","is_correct":false}]'::jsonb, 'Il secondo piatto è a base di carne o pesce, come ''il pollo''. La pasta è un primo, il tiramisù un dolce.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (7, 'Alimentazione', 'Come contorno vorrei un''insalata ______.', '[{"text":"mista","is_correct":true},{"text":"al forno","is_correct":false},{"text":"dolce","is_correct":false},{"text":"fritta","is_correct":false}]'::jsonb, 'Un contorno tipico è l''insalata ''mista''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (7, 'Alimentazione', '______ un tavolo per quattro persone, per favore.', '[{"text":"Vorremmo","is_correct":true},{"text":"Vorrei","is_correct":false},{"text":"Prendiamo","is_correct":false},{"text":"Vogliamo","is_correct":false}]'::jsonb, 'Soggetto plurale (''noi''), quindi si usa il condizionale plurale di cortesia: ''Vorremmo''.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (7, 'Alimentazione', 'Il cameriere porta il ______ alla fine del pasto per pagare.', '[{"text":"primo","is_correct":false},{"text":"menù","is_correct":false},{"text":"pane","is_correct":false},{"text":"conto","is_correct":true}]'::jsonb, 'Alla fine del pasto in ristorante si richiede e si paga il ''conto''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (7, 'Alimentazione', 'Il gorgonzola è un famoso ______ italiano.', '[{"text":"vino","is_correct":false},{"text":"dolce","is_correct":false},{"text":"formaggio","is_correct":true},{"text":"frutto","is_correct":false}]'::jsonb, 'Il gorgonzola è un tipo di formaggio erborinato.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (7, 'Alimentazione', 'Preferisco il pesce fresco alla ______.', '[{"text":"carne","is_correct":true},{"text":"pasta","is_correct":false},{"text":"verdura","is_correct":false},{"text":"frutta","is_correct":false}]'::jsonb, 'Carne e pesce sono i due tipi principali di secondi piatti di origine animale.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (7, 'Alimentazione', 'Vorrei un bicchiere di ______ rosso fermo.', '[{"text":"vino","is_correct":true},{"text":"birra","is_correct":false},{"text":"latte","is_correct":false},{"text":"acqua","is_correct":false}]'::jsonb, 'Si parla di ''rosso'' o ''bianco'' riferendosi al ''vino''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (7, 'Alimentazione', 'La colazione italiana tipica comprende cornetto e ______.', '[{"text":"insalata","is_correct":false},{"text":"pasta","is_correct":false},{"text":"pesce","is_correct":false},{"text":"caffellatte","is_correct":true}]'::jsonb, 'Il caffellatte o cappuccino si consuma tipicamente a colazione con il cornetto.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (7, 'Alimentazione', 'Per tagliare la carne al ristorante ho bisogno di un ______ affilato.', '[{"text":"coltello","is_correct":true},{"text":"bicchiere","is_correct":false},{"text":"cucchiaio","is_correct":false},{"text":"forchetta","is_correct":false}]'::jsonb, 'Si usa il coltello per tagliare.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (7, 'Alimentazione', 'Mangio la minestra con il ______.', '[{"text":"cucchiaio","is_correct":true},{"text":"coltello","is_correct":false},{"text":"forchetta","is_correct":false},{"text":"tovagliolo","is_correct":false}]'::jsonb, 'I cibi liquidi come minestre e zuppe si mangiano con il cucchiaio.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (7, 'Alimentazione', 'Mi passa la ______ per prendere gli spaghetti?', '[{"text":"forchetta","is_correct":true},{"text":"cucchiaio","is_correct":false},{"text":"coltello","is_correct":false},{"text":"tazza","is_correct":false}]'::jsonb, 'Gli spaghetti si arrotolano e si mangiano con la forchetta.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (7, 'Alimentazione', 'I vegetariani non mangiano né carne né ______.', '[{"text":"pesce","is_correct":true},{"text":"verdura","is_correct":false},{"text":"frutta","is_correct":false},{"text":"formaggio","is_correct":false}]'::jsonb, 'La dieta vegetariana esclude carne e pesce.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (7, 'Alimentazione', 'Il limoncello si beve solitamente come ______ dopo cena.', '[{"text":"colazione","is_correct":false},{"text":"primo","is_correct":false},{"text":"antipasto","is_correct":false},{"text":"digestivo","is_correct":true}]'::jsonb, 'I liquori alle erbe o agli agrumi presi a fine pasto sono detti ''digestivi''.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (7, 'Alimentazione', 'La bruschetta è un ottimo ______ per iniziare il pranzo.', '[{"text":"dolce","is_correct":false},{"text":"contorno","is_correct":false},{"text":"secondo","is_correct":false},{"text":"antipasto","is_correct":true}]'::jsonb, 'La bruschetta si serve all''inizio come antipasto.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (7, 'Alimentazione', 'Hai comprato ______ pane? No, era finito.', '[{"text":"della","is_correct":false},{"text":"lo","is_correct":false},{"text":"un","is_correct":false},{"text":"del","is_correct":true}]'::jsonb, 'Partitivo maschile singolare per pane: ''del''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (7, 'Alimentazione', 'Nel tiramisù ci va il ______ fresco.', '[{"text":"gorgonzola","is_correct":false},{"text":"pecorino","is_correct":false},{"text":"parmigiano","is_correct":false},{"text":"mascarpone","is_correct":true}]'::jsonb, 'Il formaggio cremoso fondamentale per il tiramisù è il mascarpone.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (8, 'Salute e Corpo', 'Mi fanno male ______ dopo aver camminato per ore.', '[{"text":"il dente","is_correct":false},{"text":"i piedi","is_correct":true},{"text":"la gola","is_correct":false},{"text":"la testa","is_correct":false}]'::jsonb, 'Il verbo ''fanno'' è plurale, quindi richiede un soggetto plurale: ''i piedi''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (8, 'Salute e Corpo', 'Ho mal di ______ e non riesco a deglutire bene.', '[{"text":"gola","is_correct":true},{"text":"schiena","is_correct":false},{"text":"piedi","is_correct":false},{"text":"stomaco","is_correct":false}]'::jsonb, 'La gola è la parte del corpo coinvolta nella deglutizione.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (8, 'Salute e Corpo', 'Dottore, ho la ______ a 38.5 gradi.', '[{"text":"febbre","is_correct":true},{"text":"tosse","is_correct":false},{"text":"influenza","is_correct":false},{"text":"medicina","is_correct":false}]'::jsonb, 'La temperatura corporea elevata si misura in gradi ed è la ''febbre''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (8, 'Salute e Corpo', 'Per il mal di testa, prendi questa ______ due volte al giorno.', '[{"text":"medicina","is_correct":true},{"text":"febbre","is_correct":false},{"text":"tosse","is_correct":false},{"text":"visita","is_correct":false}]'::jsonb, 'Si assume una ''medicina'' (o pillola, compressa) per curare un sintomo.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (8, 'Salute e Corpo', 'Devi andare dal ______ se i sintomi persistono.', '[{"text":"cameriere","is_correct":false},{"text":"medico","is_correct":true},{"text":"farmacista","is_correct":false},{"text":"dentista","is_correct":false}]'::jsonb, 'Si va dal medico per una diagnosi e cura.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (8, 'Salute e Corpo', 'Non ______ freddo! Metti la giacca.', '[{"text":"prendere","is_correct":true},{"text":"prendi","is_correct":false},{"text":"prendete","is_correct":false},{"text":"prendi il","is_correct":false}]'::jsonb, 'Imperativo negativo di seconda persona singolare (''tu''): non + infinito verbale (''non prendere'').', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (8, 'Salute e Corpo', 'Ragazzi, ______ la ricetta medica prima di andare in farmacia!', '[{"text":"porti","is_correct":false},{"text":"portate","is_correct":true},{"text":"porta","is_correct":false},{"text":"portiamo","is_correct":false}]'::jsonb, 'Imperativo per la seconda persona plurale (''voi''): ''portate''.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (8, 'Salute e Corpo', 'Signora, ______ questa pillola prima di andare a dormire.', '[{"text":"prenda","is_correct":true},{"text":"prendi","is_correct":false},{"text":"prendete","is_correct":false},{"text":"prendere","is_correct":false}]'::jsonb, 'Imperativo formale (cortesia) di terza persona singolare per il verbo prendere: ''prenda''.', 3, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (8, 'Salute e Corpo', 'Ho mangiato troppo ieri sera, oggi ho mal di ______.', '[{"text":"orecchie","is_correct":false},{"text":"stomaco","is_correct":true},{"text":"denti","is_correct":false},{"text":"schiena","is_correct":false}]'::jsonb, 'Mangiare in exceso causa mal di stomaco.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (8, 'Salute e Corpo', 'Ho un dente cariato, devo andare dal ______.', '[{"text":"dentista","is_correct":true},{"text":"oculista","is_correct":false},{"text":"medico","is_correct":false},{"text":"chirurgo","is_correct":false}]'::jsonb, 'Per problemi ai denti si consulta il dentista.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (8, 'Salute e Corpo', 'Se hai molto freddo e tremi, forse hai i ______.', '[{"text":"brividi","is_correct":true},{"text":"dolori","is_correct":false},{"text":"sintomi","is_correct":false},{"text":"farmaci","is_correct":false}]'::jsonb, 'Avere freddo e tremare per la febbre provoca i ''brividi''.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (8, 'Salute e Corpo', 'Ho lavorato al computer tutto il giorno, mi fa male la ______.', '[{"text":"lingua","is_correct":false},{"text":"pancia","is_correct":false},{"text":"gola","is_correct":false},{"text":"schiena","is_correct":true}]'::jsonb, 'Stare seduti a lungo provoca mal di schiena.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (8, 'Salute e Corpo', 'Usa questo ______ per calmare la tosse secca.', '[{"text":"sciroppo","is_correct":true},{"text":"cerotto","is_correct":false},{"text":"termometro","is_correct":false},{"text":"ghiaccio","is_correct":false}]'::jsonb, 'Il medicinale liquido per la tosse è lo ''sciroppo''.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (8, 'Salute e Corpo', 'Non riesco a vedere bene da lontano, devo fare una visita dall''______.', '[{"text":"dermatologo","is_correct":false},{"text":"oculista","is_correct":true},{"text":"dentista","is_correct":false},{"text":"ortopedico","is_correct":false}]'::jsonb, 'Il medico degli occhi e della vista è l''oculista.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (8, 'Salute e Corpo', 'Ho sbattuto il braccio e ora ho un ______ nero.', '[{"text":"livido","is_correct":true},{"text":"taglio","is_correct":false},{"text":"raffreddore","is_correct":false},{"text":"sintomo","is_correct":false}]'::jsonb, 'Un trauma fisico senza ferita aperta genera un ematoma o ''livido''.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (8, 'Salute e Corpo', 'Per misurare la febbre usiamo il ______.', '[{"text":"sciroppo","is_correct":false},{"text":"ricetta","is_correct":false},{"text":"termometro","is_correct":true},{"text":"medicina","is_correct":false}]'::jsonb, 'Lo strumento per misurare la temperatura corporea è il termometro.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (8, 'Salute e Corpo', 'Mi ______ la testa, penso di avere la pressione bassa.', '[{"text":"gire","is_correct":false},{"text":"fa male","is_correct":false},{"text":"fa","is_correct":false},{"text":"gira","is_correct":true}]'::jsonb, 'Espressione ''mi gira la testa'' (sento vertigini).', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (8, 'Salute e Corpo', 'L''influenza si cura riposando e stando ______.', '[{"text":"al caldo","is_correct":true},{"text":"fuori","is_correct":false},{"text":"in piedi","is_correct":false},{"text":"al freddo","is_correct":false}]'::jsonb, 'Stare riparati e coperti (''al caldo'') aiuta a guarire dall''influenza.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (8, 'Salute e Corpo', 'Non riesco a respirare bene con il naso intasato dal ______.', '[{"text":"raffreddore","is_correct":true},{"text":"tosse","is_correct":false},{"text":"dolore","is_correct":false},{"text":"livido","is_correct":false}]'::jsonb, 'Il naso chiuso è un classico sintomo del raffreddore.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (8, 'Salute e Corpo', 'Mamma, mi ______ la pancia dopo pranzo.', '[{"text":"fa male","is_correct":true},{"text":"fanno male","is_correct":false},{"text":"dolora","is_correct":false},{"text":"gira","is_correct":false}]'::jsonb, 'Pancia è singolare, richiede ''fa male''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (8, 'Salute e Corpo', 'L''infermiere mi ha fatto un''______ indolore nel braccio.', '[{"text":"visita","is_correct":false},{"text":"medicina","is_correct":false},{"text":"tosse","is_correct":false},{"text":"iniezione","is_correct":true}]'::jsonb, 'L''atto di iniettare un farmaco è un''iniezione (o puntura).', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (8, 'Salute e Corpo', 'La pelle del viso si è bruciata al sole, fa molto ______.', '[{"text":"stanco","is_correct":false},{"text":"freddo","is_correct":false},{"text":"bene","is_correct":false},{"text":"male","is_correct":true}]'::jsonb, 'Una scottatura provoca dolore (''fa male'').', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (9, 'Città e Viaggi', 'Per viaggiare in treno devi comprare un ______.', '[{"text":"tavolo","is_correct":false},{"text":"passaporto","is_correct":false},{"text":"biglietto","is_correct":true},{"text":"albergo","is_correct":false}]'::jsonb, 'Il biglietto è il titolo di viaggio necessario per salire sui mezzi pubblici.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (9, 'Città e Viaggi', 'Scusi, signore, per andare al Colosseo deve andare sempre ______.', '[{"text":"destra","is_correct":false},{"text":"dritto","is_correct":true},{"text":"sinistra","is_correct":false},{"text":"lontano","is_correct":false}]'::jsonb, 'Espressione per indicare di proseguire senza svoltare: ''andare sempre dritto''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (9, 'Città e Viaggi', 'Gira alla prima strada a ______.', '[{"text":"destra","is_correct":true},{"text":"dritto","is_correct":false},{"text":"lungo","is_correct":false},{"text":"via","is_correct":false}]'::jsonb, '''Destra'' o ''sinistra'' indicano le direzioni di svolta.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (9, 'Città e Viaggi', 'Per andare all''aeroporto prendo la ______ per evitare il traffico.', '[{"text":"bicicletta","is_correct":false},{"text":"macchina","is_correct":false},{"text":"metropolitana","is_correct":true},{"text":"piedi","is_correct":false}]'::jsonb, 'La metropolitana viaggia su binari sotterranei ed evita il traffico stradale.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (9, 'Città e Viaggi', 'Il treno per Torino parte dal ______ numero 5.', '[{"text":"biglietto","is_correct":false},{"text":"piazza","is_correct":false},{"text":"binario","is_correct":true},{"text":"fermata","is_correct":false}]'::jsonb, 'I treni partono e arrivano ai ''binari'' in stazione.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (9, 'Città e Viaggi', 'I turisti fanno molte foto al ______ storico al centro della piazza.', '[{"text":"strada","is_correct":false},{"text":"semaforo","is_correct":false},{"text":"trasporto","is_correct":false},{"text":"monumento","is_correct":true}]'::jsonb, 'I turisti fotografano i monumenti storici.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (9, 'Città e Viaggi', 'Dove posso ______ il biglietto dell''autobus?', '[{"text":"timbrare","is_correct":true},{"text":"comprare","is_correct":true},{"text":"viaggiare","is_correct":false},{"text":"perdere","is_correct":false}]'::jsonb, 'Entrambi comprare e timbrare sono corretti a seconda del contesto. Impostiamo comprare come prima scelta.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (9, 'Città e Viaggi', 'Dobbiamo ______ il biglietto prima di salire sul treno.', '[{"text":"vedere","is_correct":false},{"text":"comprare","is_correct":false},{"text":"timbrare","is_correct":true},{"text":"dormire","is_correct":false}]'::jsonb, 'In Italia è obbligatorio convalidare (timbrare) i biglietti cartacei prima di salire.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (9, 'Città e Viaggi', 'Quest''estate ______ in vacanza in Sicilia.', '[{"text":"andrò","is_correct":true},{"text":"andrei","is_correct":false},{"text":"andassi","is_correct":false},{"text":"sono andato","is_correct":false}]'::jsonb, 'Riferito al futuro prossimo (''quest''estate'' inteso come pianificato): ''andrò''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (9, 'Città e Viaggi', 'L''aereo per Milano è decollato con venti minuti di ______.', '[{"text":"viaggio","is_correct":false},{"text":"ritardo","is_correct":true},{"text":"tempo","is_correct":false},{"text":"anticipo","is_correct":false}]'::jsonb, 'Un volo decollato dopo l''orario stabilito ha accumulato ''ritardo''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (9, 'Città e Viaggi', 'Scusi, a quale ______ devo scendere per il centro?', '[{"text":"binario","is_correct":false},{"text":"stazione","is_correct":false},{"text":"via","is_correct":false},{"text":"fermata","is_correct":true}]'::jsonb, 'Per autobus e tram si parla di ''fermata''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (9, 'Città e Viaggi', 'La stazione ferroviaria si trova ______ alla cattedrale.', '[{"text":"dietro","is_correct":true},{"text":"di","is_correct":false},{"text":"a","is_correct":false},{"text":"in","is_correct":false}]'::jsonb, '''Dietro'' è preposizione di luogo che non richiede articolazione obbligatoria immediata (''dietro alla'' o ''dietro la'').', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (9, 'Città e Viaggi', 'Per andare a piedi in sicurezza dobbiamo attraversare sulle strisce ______.', '[{"text":"ferroviarie","is_correct":false},{"text":"stradali","is_correct":false},{"text":"pedonali","is_correct":true},{"text":"rosse","is_correct":false}]'::jsonb, 'Si attraversa sulle strisce pedonali.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (9, 'Città e Viaggi', 'Ho prenotato una camera doppia in un ______ vicino al centro.', '[{"text":"treno","is_correct":false},{"text":"albergo","is_correct":true},{"text":"ristorante","is_correct":false},{"text":"ufficio","is_correct":false}]'::jsonb, 'Si prenota una camera in albergo (o hotel).', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (9, 'Città e Viaggi', 'Preferisco viaggiare ______ macchina piuttosto che in aereo.', '[{"text":"a","is_correct":false},{"text":"dalla","is_correct":false},{"text":"con","is_correct":false},{"text":"in","is_correct":true}]'::jsonb, 'La preposizione per il mezzo di trasporto senza articolo è ''in macchina''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (9, 'Città e Viaggi', 'Il semaforo è rosso, dobbiamo ______.', '[{"text":"fermarci","is_correct":true},{"text":"passare","is_correct":false},{"text":"girare","is_correct":false},{"text":"correre","is_correct":false}]'::jsonb, 'Con il semaforo rosso è obbligatorio arrestarsi/fermarsi.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (9, 'Città e Viaggi', 'La mappa della città è utile per non ______.', '[{"text":"arrivare","is_correct":false},{"text":"viaggiare","is_correct":false},{"text":"trovarsi","is_correct":false},{"text":"perdersi","is_correct":true}]'::jsonb, 'La mappa serve a non smarrire la via, ovvero a non ''perdersi''.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (9, 'Città e Viaggi', 'Il viaggio in treno da Torino a Milano ______ circa un''ora.', '[{"text":"fa","is_correct":false},{"text":"costa","is_correct":false},{"text":"dura","is_correct":true},{"text":"prende","is_correct":false}]'::jsonb, 'Il tempo di percorrenza si esprime col verbo durare: ''dura''.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (9, 'Città e Viaggi', 'Per andare in un altro continente si prende l''______.', '[{"text":"aereo","is_correct":true},{"text":"treno","is_correct":false},{"text":"autobus","is_correct":false},{"text":"metropolitana","is_correct":false}]'::jsonb, 'I viaggi transcontinentali richiedono l''aereo (o la nave).', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (9, 'Città e Viaggi', 'La piazza principale della città è sempre molto ______ di turisti.', '[{"text":"vuota","is_correct":false},{"text":"piena","is_correct":true},{"text":"grande","is_correct":false},{"text":"lontana","is_correct":false}]'::jsonb, 'Si dice ''piena di'' turisti per indicare affollamento.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (9, 'Città e Viaggi', 'Il taxi ci aspetta davanti ______ stazione.', '[{"text":"in","is_correct":false},{"text":"della","is_correct":false},{"text":"la","is_correct":false},{"text":"alla","is_correct":true}]'::jsonb, 'L''avverbio di luogo ''davanti'' regge la preposizione ''a'': davanti + la stazione = ''davanti alla stazione''.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (9, 'Città e Viaggi', 'Viaggiare all''estero arricchisce molto la nostra ______.', '[{"text":"valigia","is_correct":false},{"text":"città","is_correct":false},{"text":"strada","is_correct":false},{"text":"mente","is_correct":true}]'::jsonb, 'Espressione figurata: viaggiare apre o arricchisce la ''mente''.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (10, 'Lavoro e Studio', 'Che lavoro fa tuo padre? È ______ falegname.', '[{"text":"la","is_correct":false},{"text":"un","is_correct":true},{"text":"uno","is_correct":false},{"text":"di","is_correct":false}]'::jsonb, 'Davanti a nome maschile singolare che inizia per consonante si usa l''articolo indeterminativo ''un''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (10, 'Lavoro e Studio', 'Cosa stai facendo? Sto ______ per l''esame CLA di italiano.', '[{"text":"studiando","is_correct":true},{"text":"studiato","is_correct":false},{"text":"studiare","is_correct":false},{"text":"studia","is_correct":false}]'::jsonb, 'Stare + gerundio (verbi in -are -> -ando) indica azione in corso: ''sto studiando''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (10, 'Lavoro e Studio', 'Mio fratello lavora in una grande azienda, fa l''______.', '[{"text":"impiegato","is_correct":true},{"text":"operaio","is_correct":false},{"text":"studente","is_correct":false},{"text":"insegnante","is_correct":false}]'::jsonb, 'In un ufficio aziendale lavora solitamente un ''impiegato''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (10, 'Lavoro e Studio', 'Mia madre insegna matematica al liceo, è un''______.', '[{"text":"segretaria","is_correct":false},{"text":"insegnante","is_correct":true},{"text":"ingegnere","is_correct":false},{"text":"studentessa","is_correct":false}]'::jsonb, 'Chi insegna a scuola è un''insegnante.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (10, 'Lavoro e Studio', 'Lui progetta ponti e strade, fa l''______.', '[{"text":"operaio","is_correct":false},{"text":"insegnante","is_correct":false},{"text":"ingegnere","is_correct":true},{"text":"avvocato","is_correct":false}]'::jsonb, 'La progettazione di infrastrutture è compito dell''ingegnere.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (10, 'Lavoro e Studio', 'Ieri sera i miei colleghi ______ fino a tardi in ufficio.', '[{"text":"lavoravano","is_correct":false},{"text":"sono lavorati","is_correct":false},{"text":"lavorano","is_correct":false},{"text":"hanno lavorato","is_correct":true}]'::jsonb, 'Lavorare al passato prossimo richiede l''ausiliare avere: ''hanno lavorato''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (10, 'Lavoro e Studio', 'Frequento l''______ del Politecnico di Torino.', '[{"text":"ufficio","is_correct":false},{"text":"scuola media","is_correct":false},{"text":"lavoro","is_correct":false},{"text":"università","is_correct":true}]'::jsonb, 'Il Politecnico di Torino è una rinomata università.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (10, 'Lavoro e Studio', 'Il docente sta ______ la lezione di grammatica.', '[{"text":"spiegando","is_correct":true},{"text":"spiega","is_correct":false},{"text":"spiegare","is_correct":false},{"text":"spiegato","is_correct":false}]'::jsonb, 'Stare + gerundio di spiegare (-are -> -ando) = ''sta spiegando''.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (10, 'Lavoro e Studio', 'Ho inviato il mio ______ a molte aziende per trovare lavoro.', '[{"text":"biglietto","is_correct":false},{"text":"lavoro","is_correct":false},{"text":"esame","is_correct":false},{"text":"curriculum","is_correct":true}]'::jsonb, 'Per candidarsi a un lavoro si invia il curriculum vitae (CV).', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (10, 'Lavoro e Studio', 'Il medico lavora in ______.', '[{"text":"ufficio","is_correct":false},{"text":"ospedale","is_correct":true},{"text":"scuola","is_correct":false},{"text":"cantiere","is_correct":false}]'::jsonb, 'Il luogo di lavoro tipico di medici e infermieri è l''ospedale o la clinica.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (10, 'Lavoro e Studio', 'Che lavoro ______ fare da grande? L''ingegnere.', '[{"text":"vorresti","is_correct":true},{"text":"vuoi","is_correct":false},{"text":"vorrai","is_correct":false},{"text":"vorrebbe","is_correct":false}]'::jsonb, 'Condizionale di cortesia/desiderio per la seconda persona singolare (''tu''): ''vorresti''.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (10, 'Lavoro e Studio', 'La segretaria sta scrivendo una ______ importante.', '[{"text":"macchina","is_correct":false},{"text":"lezione","is_correct":false},{"text":"lettera","is_correct":true},{"text":"strada","is_correct":false}]'::jsonb, 'Compito tipico di segreteria è redigere e scrivere lettere o email.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (10, 'Lavoro e Studio', 'Per superare l''esame CLA bisogna ottenere almeno ______ punti su 30.', '[{"text":"20","is_correct":false},{"text":"30","is_correct":false},{"text":"18","is_correct":true},{"text":"10","is_correct":false}]'::jsonb, 'La sufficienza negli esami universitari italiani è 18/30.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (10, 'Lavoro e Studio', 'L''operaio lavora in ______.', '[{"text":"ufficio","is_correct":false},{"text":"fabbrica","is_correct":true},{"text":"ospedale","is_correct":false},{"text":"università","is_correct":false}]'::jsonb, 'L''operaio lavora tipicamente in fabbrica o nei cantieri.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (10, 'Lavoro e Studio', 'La mia routine quotidiana ______ alle 7 con una tazza di caffè.', '[{"text":"lavora","is_correct":false},{"text":"finisce","is_correct":false},{"text":"inizia","is_correct":true},{"text":"studia","is_correct":false}]'::jsonb, 'La giornata o routine comincia (''inizia'') al mattino.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (10, 'Lavoro e Studio', 'Chi ripara i tubi dell''acqua in casa è l''______.', '[{"text":"falegname","is_correct":false},{"text":"elettricista","is_correct":false},{"text":"muratore","is_correct":false},{"text":"idraulico","is_correct":true}]'::jsonb, 'L''idraulico si occupa di tubature e impianti idrici.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (10, 'Lavoro e Studio', 'Domani ho un colloquio di ______ in una nuova azienda.', '[{"text":"esame","is_correct":false},{"text":"studio","is_correct":false},{"text":"lavoro","is_correct":true},{"text":"corso","is_correct":false}]'::jsonb, 'Il colloquio per essere assunti è detto colloquio di lavoro.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (10, 'Lavoro e Studio', 'Lo studente universitario deve sostenere molti ______.', '[{"text":"lezioni","is_correct":false},{"text":"libri","is_correct":false},{"text":"esami","is_correct":true},{"text":"lavori","is_correct":false}]'::jsonb, 'Sostenere gli esami è l''attività di verifica per gli studenti universitari.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (10, 'Lavoro e Studio', 'Il falegname realizza mobili in ______.', '[{"text":"ferro","is_correct":false},{"text":"carta","is_correct":false},{"text":"plastica","is_correct":false},{"text":"legno","is_correct":true}]'::jsonb, 'Il falegname lavora e modella il legno.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (10, 'Lavoro e Studio', 'La riunione con il capo comincia ______ dieci.', '[{"text":"dalle","is_correct":false},{"text":"a","is_correct":false},{"text":"nelle","is_correct":false},{"text":"alle","is_correct":true}]'::jsonb, 'Con le ore si usa la preposizione articolata: a + le = ''alle'' dieci.', 1, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (10, 'Lavoro e Studio', 'Mio padre va in ______ l''anno prossimo dopo 40 anni di lavoro.', '[{"text":"vacanza","is_correct":false},{"text":"università","is_correct":false},{"text":"pensione","is_correct":true},{"text":"ufficio","is_correct":false}]'::jsonb, 'Cessare l''attività lavorativa per raggiunti limiti d''età significa andare in ''pensione''.', 2, 'dieci_a2');
INSERT INTO questions (milestone_id, topic, question_text, options, explanation, difficulty, source) VALUES (10, 'Lavoro e Studio', 'Stiamo ______ per completare il progetto entro stasera.', '[{"text":"lavora","is_correct":false},{"text":"lavorato","is_correct":false},{"text":"lavorare","is_correct":false},{"text":"lavorando","is_correct":true}]'::jsonb, 'Stiamo + gerundio di lavorare (-are -> -ando) = ''stiamo lavorando''.', 1, 'dieci_a2');
